import { readFileSync } from "node:fs";
import { join } from "node:path";
import { DOCS_GROUPS } from "~/shared/docs/manifest";
import { renderDoc } from "~/shared/docs/render";

/** The source of src/shared/docs/generated.ts, built from docs/*.md under `root`. Node only. */
export function buildDocsModule(root: string) {
  const pages = DOCS_GROUPS.flatMap((group) => group.files.map((file) => renderDoc(file, readFileSync(join(root, "docs", `${file}.md`), "utf8"))));
  return [
    "// Generated by scripts/build-docs.ts from docs/*.md. Do not edit; run `npm run docs:build`.",
    'import { type DocPage } from "~/shared/docs/render";',
    "",
    `export const DOC_PAGES: DocPage[] = ${JSON.stringify(pages, null, 2)};`,
    "",
  ].join("\n");
}
